#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "session_timeline_document_candidate.h"
#include <chrono>
#include <limits>
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("session required");SessionTimelineDocumentCandidate doc(loadGraph(argv[1]));uint32_t layer=UINT32_MAX;for(uint32_t i=0;i<doc.graph().elements.size();++i){const auto&e=doc.graph().elements[i];if(doc.graph().strings.at(e.type)!="DmeFloatLogLayer")continue;KeyTrack track(doc.graph(),e);if(track.values->type==17&&track.values->values.size()>1){layer=i;break;}}if(layer==UINT32_MAX)throw std::runtime_error("no float key fixture");KeyTrack original(doc.graph(),doc.graph().elements[layer]);auto times=original.times->values;auto first=original.values->values[0].wire,second=original.values->values[1].wire;float changed[2]={wireFloat(original.values->values[0])==123.f?124.f:123.f,wireFloat(original.values->values[1])==456.f?457.f:456.f};
 if(!doc.setFloatKeyValue(layer,0,changed[0])||!doc.setFloatKeyValue(layer,1,changed[1])||!doc.dirty())throw std::runtime_error("two key edits");if(doc.setFloatKeyValue(layer,1,changed[1]))throw std::runtime_error("equal key recorded");if(doc.undo()!=1||!doc.dirty()||KeyTrack(doc.graph(),doc.graph().elements[layer]).values->values[1].wire!=second)throw std::runtime_error("indexed dirty undo");if(doc.undo()!=1||doc.dirty()||KeyTrack(doc.graph(),doc.graph().elements[layer]).values->values[0].wire!=first)throw std::runtime_error("key undo restoration");if(doc.redo()!=1||doc.redo()!=1)throw std::runtime_error("key redo");KeyTrack after(doc.graph(),doc.graph().elements[layer]);if(wireFloat(after.values->values[0])!=changed[0]||wireFloat(after.values->values[1])!=changed[1])throw std::runtime_error("key redo values");for(size_t i=0;i<times.size();++i)if(times[i].wire!=after.times->values[i].wire)throw std::runtime_error("key edit changed timing");bool rejected=false;try{doc.setFloatKeyValue(layer,after.values->values.size(),1.f);}catch(const std::runtime_error&){rejected=true;}if(!rejected)throw std::runtime_error("invalid key accepted");const auto stable=after.values->values[0].wire;for(float invalid:{std::numeric_limits<float>::quiet_NaN(),std::numeric_limits<float>::infinity(),-std::numeric_limits<float>::infinity()}){const bool dirtyBefore=doc.dirty();rejected=false;try{doc.setFloatKeyValue(layer,0,invalid);}catch(const std::runtime_error&){rejected=true;}if(!rejected||doc.dirty()!=dirtyBefore||KeyTrack(doc.graph(),doc.graph().elements[layer]).values->values[0].wire!=stable)throw std::runtime_error("non-finite key edit was accepted or changed document");}auto path="work/float-key-roundtrip-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count())+".dmx";doc.saveAs(path.c_str());if(doc.dirty())throw std::runtime_error("saved key edit remains dirty");auto reopened=loadGraph(path.c_str());KeyTrack persisted(reopened,reopened.elements.at(layer));if(wireFloat(persisted.values->values[0])!=changed[0]||wireFloat(persisted.values->values[1])!=changed[1])throw std::runtime_error("saved key values did not reopen");for(size_t i=0;i<times.size();++i)if(times[i].wire!=persisted.times->values[i].wire)throw std::runtime_error("reopened key timing changed");std::cout<<"document_float_key_checks=11 finite_guard save_reload layer="<<layer<<"\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
